-- Lee 2026-11-04 "니가 건드려서 문제된거는 고치면되는데 … 일단 수정해": 내가 넣은 값 occupation_code, category만 고침.
-- 입구 ingest_job의 기존 공고 고치기(job_id + update_fields)로만 — 규칙 트리거·공개 게이트 그대로.
select public.ingest_job($ingest${"title": "Nhà hàng Thanh Phệ tuyển 01 tạp vụ – rửa bát, dọn vệ sinh, bao ăn ở", "company": "Nhà hàng Thanh Phệ", "category": "am_thuc_do_uong", "occupation_code": "9402", "occupation_evidence": "Rửa bát, lau dọn vệ sinh.", "salary": "Thỏa thuận", "location": "Nhà hàng Thanh Phệ, Phân Khu B, KCN Thuận Thành 3, Bắc Ninh", "employer_phone": "0968568885", "num_hires": 1, "description": "[source:facebook] THÔNG BÁO TUYỂN DỤNG\nVỊ TRÍ: Tạp vụ( 1 người ).\nMô tả công việc:\n• Rửa bát, lau dọn vệ sinh.\n• Trung thực, khoẻ mạnh,sạch sẽ, gọn gàng.\n• Bao ăn ở\n• Lương thoả thuận.\nĐịa điểm làm việc:\n• Nhà hàng Thanh Phệ, Phân Khu B , kcn thuận thành 3, Bắc Ninh\nCách thức ứng tuyển:\nLiên hệ qua : 0968568885", "source_text": "THÔNG BÁO TUYỂN DỤNG\nVỊ TRÍ: Tạp vụ( 1 người ).\nMô tả công việc:\n• Rửa bát, lau dọn vệ sinh.\n• Trung thực, khoẻ mạnh,sạch sẽ, gọn gàng.\n• Bao ăn ở\n• Lương thoả thuận.\nĐịa điểm làm việc:\n• Nhà hàng Thanh Phệ, Phân Khu B , kcn thuận thành 3, Bắc Ninh\nCách thức ứng tuyển:\nLiên hệ qua : 0968568885", "source_url": "https://www.facebook.com/groups/timvieclamthembacninh/posts/1473151661616971/", "job_id": 5421, "update_fields": ["occupation_code", "category"], "channel": "sql_file"}$ingest$::jsonb) as job_id \gset
select step, outcome from public.job_ingest_log where raw_id = (select max(id) from public.job_ingest_raw where job_id = :job_id) order by array_position(array['preserve','dedup','occupation','location','publication'], step);
select id, occupation_code, category, salary, active, admin_hidden from public.local_jobs where id = :job_id;
